package com.jlas.learning.service.impl;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.util.HashMap;
import java.util.Map;

/** [JLAS-W0108] Owner 2026-10-24 (D3-03, supersedes OD-13): a Kanji card shows its Vietnamese meaning (VNJPClub, from
 * the compiled books) next to the Hán Việt, never English. Learning's own copy ({@code learning/kanji-meaning-vi.json},
 * generated by {@code tools/learning-data-extract/build_kanji_meaning_vi.mjs}) because the shared {@code kanji.meaning_vi}
 * belongs to Dictionary and is empty for these characters. */
@Component
public class KanjiMeaningCatalog {
    static final String RESOURCE = "learning/kanji-meaning-vi.json";
    static final String ATTRIBUTION = "Nghĩa tiếng Việt theo VNJPClub; chữ VNJPClub chưa có nghĩa do KotsuKotsu bổ sung.";
    private final Map<String, String> meanings;

    public KanjiMeaningCatalog() {
        try (InputStream in = KanjiMeaningCatalog.class.getClassLoader().getResourceAsStream(RESOURCE)) {
            if (in == null) throw new IllegalStateException("Missing " + RESOURCE);
            Map<String, String> byKanji = new HashMap<>();
            new ObjectMapper().readTree(in).path("kanji").fields()
                    .forEachRemaining(entry -> byKanji.put(entry.getKey(), entry.getValue().asText()));
            meanings = Map.copyOf(byKanji);
        } catch (IOException exception) {
            throw new UncheckedIOException(exception);
        }
    }

    /** "gặp gỡ; cuộc họp", or null when the character is not in a compiled book. */
    public String meaningVi(String character) {
        return character == null ? null : meanings.get(character);
    }

    public String attribution() {
        return ATTRIBUTION;
    }
}
